const seasonYear = inputData.season_year || currentYear;

const message = `🎾🏆 *RETROSPECTIVA ${seasonYear} LIBERADA NO RANKING MONTREAL!* 🏆🎾\n\nA temporada oficial de *${seasonYear}* encerrou em 30 de Novembro e os números finais estão consolidados no saibro da Montreal! 🔥\n\n✨ *O que você encontra no aplicativo:*\n🥇 *Hall de Campeões & Pódios:* Conheça os atletas que conquistaram o 1º, 2º e 3º lugar em cada categoria e nível!\n📊 *Recordes do Ano:* Descubra quem foi o Fominha do Ano, o Maior Pontuador, o Mais Eficiente e os Grandes Duelos do clube!\n📸 *Seu Story de Atleta (Estilo Spotify Wrapped):* Veja quantas partidas você disputou, seus pontos, suas vitórias, seu maior rival e gere seu card exclusivo para postar nos Stories do Instagram!\n\n👉 *Acesse sua Retrospectiva agora mesmo:*\n🔗 https://ranking.montrealtenis.com.br/#/ranking\n\nCompartilhe seu Story e marque a Montreal: *@montreal.tenisclube* 🎾✨`;

return [{
  json: {
    number: "120363428928893345@g.us",
    text: message,
    season_year: seasonYear
  }
}];

